<?php
declare(strict_types=1);
require __DIR__.'/../app/bootstrap.php';
$error='';$notice='';
$loginCsrfRejected=$_SERVER['REQUEST_METHOD']==='POST'&&($_POST['mode']??'')==='login'&&!csrf_valid();
if ($loginCsrfRejected) {
    http_response_code(403);$error='Oturum doğrulaması başarısız. Lütfen yeniden giriş yapın.';
} elseif ($_SERVER['REQUEST_METHOD']==='POST') {
    csrf();$mode=$_POST['mode']??'';
    if($mode==='login') {
        $ip=$_SERVER['REMOTE_ADDR']??'';
        $attempt=query('SELECT failures,TIMESTAMPDIFF(SECOND,last_attempt,UTC_TIMESTAMP()) age FROM login_attempts WHERE ip=?',[$ip])[0]??null;
        if($attempt && (int)$attempt['failures']>=10 && (int)$attempt['age']<900) $error='Çok sayıda giriş denemesi. 15 dakika sonra tekrar deneyin.';
        else {
            $user=query('SELECT * FROM users WHERE username=?',[mb_substr(trim(is_string($_POST['username']??null)?$_POST['username']:''),0,64)])[0]??null;
            $password=is_string($_POST['password']??null)?$_POST['password']:'';
            $valid=$user && (int)$user['enabled']===1 && strlen($password)<=1024 && password_verify($password,$user['password_hash']);
            if($valid) {
                session_regenerate_id(true);$_SESSION['uid']=$user['id'];$_SESSION['session_version']=(int)$user['session_version'];$_SESSION['username']=$user['username'];$_SESSION['must_change']=(bool)$user['must_change'];$_SESSION['last_seen']=time();$_SESSION['csrf']=bin2hex(random_bytes(32));
                execute('DELETE FROM login_attempts WHERE ip=?',[$ip]);audit('login');header('Location: /');exit;
            }
            execute('INSERT INTO login_attempts(ip,failures,last_attempt) VALUES(?,1,UTC_TIMESTAMP()) ON DUPLICATE KEY UPDATE failures=IF(TIMESTAMPDIFF(SECOND,last_attempt,UTC_TIMESTAMP())>=900,1,failures+1),last_attempt=UTC_TIMESTAMP()',[$ip]);
            audit('failed_login');$error='Kullanıcı adı veya parola hatalı.';
        }
    } elseif($mode==='logout') { audit('logout');session_unset();session_destroy();header('Location: /');exit; }
    elseif($mode==='password' && authenticated()) {
        require_once __DIR__.'/../app/account-password.php';
        try{
            $version=(int)$_SESSION['session_version'];
            if(!account_change_password((int)$_SESSION['uid'],$version,$_POST['current_password']??null,$_POST['new_password']??null,$_POST['confirm_password']??null)){
                clear_authenticated_session();$error='Hesabınız başka bir oturumda değişti. Yeniden giriş yapın.';
            }else{
                $_SESSION['must_change']=false;$_SESSION['session_version']=$version+1;session_regenerate_id(true);$_SESSION['csrf']=bin2hex(random_bytes(32));header('Location: /');exit;
            }
        }catch(InvalidArgumentException $e){$error=$e->getMessage();}
    }
}
$logged=authenticated()&&!$loginCsrfRejected;$passwordPage=$logged && (($_SESSION['must_change']??true)||isset($_GET['account']));
try{$selectedDevice=$logged?fg_selected_device():null;}catch(FortigateAccessError $e){http_response_code(403);exit(h($e->getMessage()).' · <a href="/">İzinli cihazlara dön</a>');}catch(InvalidArgumentException $e){http_response_code(422);exit(h($e->getMessage()).' · <a href="/">Cihaz seçimine dön</a>');}
require_once __DIR__.'/../app/retention.php';
$analysisWindowDays=$logged?retention_fast_days():FLS_RETENTION_DEFAULT_FAST_DAYS;
$accountTheme=$logged?(query('SELECT theme FROM user_preferences WHERE user_id=?',[$_SESSION['uid']])[0]['theme']??''):'';
?><!doctype html>
<html lang="tr" data-fg-device="<?=!empty($selectedDevice['id'])?(int)$selectedDevice['id']:''?>" data-user-role="<?=$logged?h($_SESSION['role']??'analyst'):''?>" data-user-id="<?=$logged?(int)$_SESSION['uid']:''?>" data-account-theme="<?=h($accountTheme)?>"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="light dark"><meta name="theme-color" content="#f3f6fb"><meta name="description" content="FLS · FortiGate log analizi ve imzalı arşiv yönetimi."><meta name="csrf-token" content="<?=h($_SESSION['csrf'])?>"><title>FLS · Fortigate Log Sniffer</title><link rel="icon" href="/assets/fls-logo.png?v=33" type="image/png"><script src="/assets/theme.js?v=34"></script><script src="/assets/sidebar.js?v=72.1"></script><link rel="stylesheet" href="/assets/app.css?v=19"><link rel="stylesheet" href="/assets/interface.css?v=57"><link rel="stylesheet" href="/assets/workspace.css?v=57"><link rel="stylesheet" href="/assets/workspace-ux.css?v=72"><link rel="stylesheet" href="/assets/event-columns.css?v=30"><link rel="stylesheet" href="/assets/event-views.css?v=32"><link rel="stylesheet" href="/assets/theme.css?v=34"><link rel="stylesheet" href="/assets/maintenance.css?v=72"><?php if($logged&&($_SESSION['role']??'')==='admin'):?><link rel="stylesheet" href="/assets/power.css?v=1"><link rel="stylesheet" href="/assets/disk-management.css?v=1"><?php endif;?><link rel="stylesheet" href="/assets/settings.css?v=72"><?php if($logged&&!$passwordPage&&($_SESSION['role']??'')==='admin'):?><link rel="stylesheet" href="/assets/system-backups.css?v=75.0"><link rel="stylesheet" href="/assets/operations.css?v=74"><?php endif;?><link rel="stylesheet" href="/assets/onboarding.css?v=60"><link rel="stylesheet" href="/assets/retention.css?v=69"><link rel="stylesheet" href="/assets/license.css?v=72"><link rel="stylesheet" href="/assets/cold-storage.css?v=72"><link rel="stylesheet" href="/assets/cold-browse.css?v=72"><link rel="s